import java.io.*;
import java.util.*;

abstract class BankAccount {
    protected double balance;

    public BankAccount(double balance) {
        this.balance = balance;
    }

    public abstract void deposit(double amount);
    public abstract String withdraw(double amount);

    public double getBalance() {
        return balance;
    }
}

class SavingsAccount extends BankAccount {
    private static final double MIN_BALANCE = 1000.0;

    public SavingsAccount(double balance) {
        super(balance);
    }

    @Override
    public void deposit(double amount) {
        balance += amount;
    }

    @Override
    public String withdraw(double amount) {
        if (balance - amount < MIN_BALANCE) {
            return "Insufficient balance";
        }
        balance -= amount;
        return "Success";
    }
}

class CurrentAccount extends BankAccount {
    public CurrentAccount(double balance) {
        super(balance);
    }

    @Override
    public void deposit(double amount) {
        balance += amount;
    }

    @Override
    public String withdraw(double amount) {
        if (balance < amount) {
            return "Insufficient balance";
        }
        balance -= amount;
        return "Success";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String accountType = sc.nextLine().trim();
        double initialBalance = Double.parseDouble(sc.nextLine().trim());
        String transactionType = sc.nextLine().trim();
        double transactionAmount = Double.parseDouble(sc.nextLine().trim());

        BankAccount account;

        if (accountType.equalsIgnoreCase("Savings")) {
            account = new SavingsAccount(initialBalance);
        } else {
            account = new CurrentAccount(initialBalance);
        }

        if (transactionType.equalsIgnoreCase("Deposit")) {
            account.deposit(transactionAmount);
            System.out.println((int)account.getBalance());
        } else {
            String result = account.withdraw(transactionAmount);
            if (result.equals("Insufficient balance")) {
                System.out.println("Insufficient balance");
            } else {
                System.out.println((int)account.getBalance());
            }
        }

        sc.close();
    }
}
